const upsertExternalFeedbackContributor = `-- name: UpsertExternalFeedbackContributor :one
WITH existing AS (
    SELECT existing_contributor.id
    FROM feedback_contributors existing_contributor
    WHERE existing_contributor.portal_id = $1
      AND existing_contributor.external_id = $2
      AND existing_contributor.kind = 'external'
    ORDER BY existing_contributor.created_at, existing_contributor.id
    LIMIT 1
    FOR UPDATE
), updated AS (
    UPDATE feedback_contributors contributor
    SET kind = 'external',
        user_id = NULL,
        external_id = $2,
        email = $3,
        email_verified_at = $4,
        display_name = CAST($5 AS text),
        avatar_url = CAST($6 AS text),
        public_masked = false,
        last_seen_at = $4,
        updated_at = $4
    FROM existing
    WHERE contributor.id = existing.id
    RETURNING contributor.id,
              contributor.portal_id,
              contributor.user_id,
              contributor.kind,
              contributor.email,
              contributor.email_verified_at,
              contributor.display_name,
              contributor.avatar_url,
              contributor.external_id,
              contributor.public_masked,
              contributor.blocked_at,
              contributor.blocked_reason,
              contributor.last_seen_at,
              contributor.created_at,
              contributor.updated_at
), inserted AS (
    INSERT INTO feedback_contributors (
        portal_id,
        kind,
        external_id,
        email,
        email_verified_at,
        display_name,
        avatar_url,
        last_seen_at
    )
    SELECT portal.id,
           'external',
           $2,
           $3,
           $4,
           CAST($5 AS text),
           CAST($6 AS text),
           $4
    FROM feedback_portals portal
    WHERE portal.id = $1
      AND portal.is_public = true
      AND NOT EXISTS (SELECT 1 FROM existing)
    RETURNING id,
              portal_id,
              user_id,
              kind,
              email,
              email_verified_at,
              display_name,
              avatar_url,
              external_id,
              public_masked,
              blocked_at,
              blocked_reason,
              last_seen_at,
              created_at,
              updated_at
)
SELECT updated.id,
       updated.portal_id,
       updated.user_id,
       CAST(updated.kind AS text) AS kind,
       updated.email,
       updated.email_verified_at,
       CAST(updated.display_name AS text) AS display_name,
       updated.avatar_url,
       updated.external_id,
       updated.public_masked,
       updated.blocked_at,
       updated.blocked_reason,
       updated.last_seen_at,
       updated.created_at,
       updated.updated_at
FROM updated
UNION ALL
SELECT inserted.id,
       inserted.portal_id,
       inserted.user_id,
       CAST(inserted.kind AS text) AS kind,
       inserted.email,
       inserted.email_verified_at,
       CAST(inserted.display_name AS text) AS display_name,
       inserted.avatar_url,
       inserted.external_id,
       inserted.public_masked,
       inserted.blocked_at,
       inserted.blocked_reason,
       inserted.last_seen_at,
       inserted.created_at,
       inserted.updated_at
FROM inserted
`

